data class TripLink(val tripId: TripId)
fun parseTrusted(uri: Uri): TripLink? =
  uri.takeIf { it.scheme == "https" && it.host == "travel.example" }
    ?.pathSegments?.takeIf { it.size == 2 && it[0] == "trips" }
    ?.let { TripLink(TripId.parse(it[1])) }

